import 'package:dio/dio.dart';

import '../../services/api_endpoints.dart';
import '../../services/api_service.dart';

class PasswordResetService {
  final ApiService _api = ApiService();

  /// Changes the password using the one-time reset key
  /// generated by Frappe.
  ///
  /// The key normally comes from the reset link sent by ERPNext/Frappe.
  Future<void> resetPassword({
    required String key,
    required String newPassword,
  }) async {
    try {
      final Response response = await _api.post(
        url: ApiEndpoints.updatePassword,
        requiresAuth: false,
        data: {
          "key": key,
          "new_password": newPassword,
        },
      );

      final data = response.data;

      if (data is Map<String, dynamic>) {
        final message = data["message"];

        // Frappe normally returns a successful message.
        // If it explicitly reports an error, surface it.
        if (message is Map<String, dynamic>) {
          final error = message["error"]?.toString();
          if (error != null && error.isNotEmpty) {
            throw Exception(error);
          }
        }
      }
    } on DioException catch (e) {
      final responseData = e.response?.data;

      String message = "Unable to reset password.";

      if (responseData is Map<String, dynamic>) {
        final serverMessage =
            responseData["message"]?.toString() ??
            responseData["exc_type"]?.toString();

        if (serverMessage != null && serverMessage.isNotEmpty) {
          message = serverMessage;
        }
      } else if (e.message != null && e.message!.isNotEmpty) {
        message = e.message!;
      }

      throw Exception(message);
    } catch (e) {
      throw Exception(e.toString());
    }
  }
}
